<template>
  <div class="category-management">
    <h2>卫星地面融合网络社区-分类管理</h2>

    <!-- 操作按钮 -->
    <el-card class="action-card">
      <el-button type="primary" icon="el-icon-plus" @click="addCategory">添加分类</el-button>
    </el-card>

    <!-- 分类列表 -->
    <el-card>
      <el-table :data="categories" style="width: 100%" v-loading="loading">
        <el-table-column prop="id" label="ID" width="60"></el-table-column>
        <el-table-column prop="categoryname" label="分类名称" width="200"></el-table-column>
        <el-table-column prop="description" label="描述" show-overflow-tooltip></el-table-column>
        <el-table-column label="图标" width="100">
          <template slot-scope="scope">
            <img v-if="scope.row.avatar" :src="scope.row.avatar" class="category-avatar" />
          </template>
        </el-table-column>
        <el-table-column label="操作" width="150" fixed="right">
          <template slot-scope="scope">
            <el-button type="text" size="small" @click="editCategory(scope.row)">编辑</el-button>
            <el-button type="text" size="small" class="danger-text" @click="deleteCategory(scope.row)">删除</el-button>
          </template>
        </el-table-column>
      </el-table>
    </el-card>

    <!-- 添加/编辑分类对话框 -->
    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="500px">
      <el-form :model="categoryForm" label-width="100px">
        <el-form-item label="分类名称">
          <el-input v-model="categoryForm.categoryname" placeholder="请输入分类名称"></el-input>
        </el-form-item>
        <el-form-item label="描述">
          <el-input v-model="categoryForm.description" type="textarea" :rows="3" placeholder="请输入分类描述"></el-input>
        </el-form-item>
        <el-form-item label="图标">
          <div class="avatar-upload">
            <el-radio-group v-model="avatarType" class="radio-group">
              <el-radio label="url">URL地址</el-radio>
              <el-radio label="upload">上传图片</el-radio>
            </el-radio-group>
            <el-input v-if="avatarType === 'url'" v-model="categoryForm.avatar" placeholder="请输入图标URL"></el-input>
            <el-upload v-else
              class="avatar-uploader"
              action="/api/upload"
              :show-file-list="false"
              :on-success="handleAvatarSuccess"
              :before-upload="beforeAvatarUpload">
              <img v-if="categoryForm.avatar" :src="categoryForm.avatar" class="avatar">
              <i v-else class="el-icon-plus avatar-uploader-icon"></i>
            </el-upload>
          </div>
        </el-form-item>
      </el-form>
      <span slot="footer">
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" @click="confirmSave">保存</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
import { getCategorys, saveCategory, deleteCategory as deleteCategoryApi } from '@/api/category'

export default {
  name: 'CategoryManagement',
  data() {
    return {
      categories: [],
      loading: false,
      dialogVisible: false,
      dialogTitle: '添加分类',
      categoryForm: {
        id: null,
        categoryname: '',
        description: '',
        avatar: ''
      },
      avatarType: 'url'
    }
  },
  created() {
    this.loadCategories()
  },
  methods: {
    async loadCategories() {
      this.loading = true
      try {
        const res = await getCategorys()
        this.categories = res.data || []
      } catch (error) {
        this.$message.error('加载分类列表失败')
      } finally {
        this.loading = false
      }
    },
    async confirmSave() {
      if (!this.categoryForm.categoryname) {
        this.$message.warning('请输入分类名称')
        return
      }

      try {
        await saveCategory(this.categoryForm)
        this.$message.success('保存成功')
        this.dialogVisible = false
        this.loadCategories()
      } catch (error) {
        this.$message.error('保存失败')
      }
    },
    async deleteCategory(category) {
      try {
        await this.$confirm(`确定要删除分类「${category.categoryname}」吗？`, '警告', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        })

        await deleteCategoryApi(category.id)
        this.$message.success('删除成功')
        this.loadCategories()
      } catch (error) {
        if (error !== 'cancel') {
          this.$message.error('删除失败')
        }
      }
    },
    handleAvatarSuccess(response, file) {
      if (response.code === 0) {
        this.categoryForm.avatar = response.data.url
      } else {
        this.$message.error('图片上传失败')
      }
    },
    beforeAvatarUpload(file) {
      const isImage = file.type.startsWith('image/')
      const isLt2M = file.size / 1024 / 1024 < 2

      if (!isImage) {
        this.$message.error('请上传图片格式文件')
        return false
      }
      if (!isLt2M) {
        this.$message.error('图片大小不能超过 2MB')
        return false
      }
      return true
    },
    addCategory() {
      this.dialogTitle = '添加分类'
      this.avatarType = 'url'
      this.categoryForm = {
        id: null,
        categoryname: '',
        description: '',
        avatar: ''
      }
      this.dialogVisible = true
    },
    editCategory(category) {
      this.dialogTitle = '编辑分类'
      this.avatarType = category.avatar && category.avatar.startsWith('http') ? 'url' : 'upload'
      this.categoryForm = {
        id: category.id,
        categoryname: category.categoryname,
        description: category.description,
        avatar: category.avatar
      }
      this.dialogVisible = true
    }
  }
}
</script>

<style scoped>
.category-management {
  padding: 20px;
}

.category-management h2 {
  margin-bottom: 20px;
  font-size: 24px;
  color: #303133;
}

.action-card {
  margin-bottom: 20px;
}

.category-avatar {
  width: 40px;
  height: 40px;
  object-fit: cover;
  border-radius: 4px;
}

.danger-text {
  color: #F56C6C;
}

.danger-text:hover {
  color: #f66;
}

.avatar-upload {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.radio-group {
  margin-bottom: 10px;
}

.avatar-uploader {
  border: 1px dashed #d9d9d9;
  border-radius: 6px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.avatar-uploader:hover {
  border-color: #409EFF;
}

.avatar-uploader-icon {
  font-size: 28px;
  color: #8c939d;
  width: 178px;
  height: 178px;
  line-height: 178px;
  text-align: center;
}

.avatar {
  width: 178px;
  height: 178px;
  display: block;
}
</style>



